#include <vector>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <algorithm>

using namespace std;

class Solution {
public:
    string findCommonResponse(vector<vector<string>>& responses) {
        unordered_map<string, int> count;
        for (const auto& r : responses) {
            unordered_set<string> uniqueItems(r.begin(), r.end());
            for (const auto& item : uniqueItems) count[item]++;
        }
        int maxFreq = 0;
        for (const auto& p : count) maxFreq = max(maxFreq, p.second);
        string ans = "";
        for (const auto& [item, freq] : count) {
            if (freq == maxFreq) {
                if (ans.empty() || item < ans) ans = item;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public String findCommonResponse(List<List<String>> responses) {
        Map<String, Integer> count = new HashMap<>();
        for (List<String> r : responses) {
            Set<String> uniqueItems = new HashSet<>(r);
            for (String item : uniqueItems) {
                count.put(item, count.getOrDefault(item, 0) + 1);
            }
        }
        int maxFreq = 0;
        for (int freq : count.values()) maxFreq = Math.max(maxFreq, freq);
        String ans = "";
        for (Map.Entry<String, Integer> entry : count.entrySet()) {
            if (entry.getValue() == maxFreq) {
                if (ans.isEmpty() || entry.getKey().compareTo(ans) < 0) {
                    ans = entry.getKey();
                }
            }
        }
        return ans;
    }
}

var findCommonResponse = function(responses) {
    const count = new Map();
    for (const r of responses) {
        const uniqueItems = new Set(r);
        for (const item of uniqueItems) {
            count.set(item, (count.get(item) || 0) + 1);
        }
    }
    let maxFreq = 0;
    for (const freq of count.values()) {
        if (freq > maxFreq) maxFreq = freq;
    }
    let ans = "";
    for (const [item, freq] of count.entries()) {
        if (freq === maxFreq) {
            if (ans === "" || item < ans) ans = item;
        }
    }
    return ans;
};
